/**
 * This allows for blocks to randomly offset like foliage does in the Vanilla game
 * @minecraft minecraft:random_offset
 */
export interface RandomOffsetComponent {
  /**
   * Random offset on the x-axis
   * @minecraft x
   */
  x?: {
    /**
     * This is the range of possible values we can pick from
     * @minecraft range
     */
    range?: {
      /**
       * Lower bound
       * @minecraft min
       */
      min?: number;
      /**
       * Upper bound
       * @minecraft max
       */
      max?: number;
    };
    /**
     * This is the equally spaced steps across the given range. Provide 0 for all possible values in the range
     * @minecraft steps
     */
    steps?: number;
  };
  /**
   * Random offset on the y-axis
   * @minecraft y
   */
  y?: {
    /**
     * This is the range of possible values we can pick from
     * @minecraft range
     */
    range?: {
      /**
       * Lower bound
       * @minecraft min
       */
      min?: number;
      /**
       * Upper bound
       * @minecraft max
       */
      max?: number;
    };
    /**
     * This is the equally spaced steps across the given range. Provide 0 for all possible values in the range
     * @minecraft steps
     */
    steps?: number;
  };
  /**
   * Random offset on the z-axis
   * @minecraft z
   */
  z?: {
    /**
     * This is the range of possible values we can pick from
     * @minecraft range
     */
    range?: {
      /**
       * Lower bound
       * @minecraft min
       */
      min?: number;
      /**
       * Upper bound
       * @minecraft max
       */
      max?: number;
    };
    /**
     * This is the equally spaced steps across the given range. Provide 0 for all possible values in the range
     * @minecraft steps
     */
    steps?: number;
  };
}

